const labels={id:'对象编号',name:'名称',type:'类型',kind:'类别',city:'盟市',county:'旗县',region:'行政区',source:'数据来源',owner:'责任单位',approval:'来源状态',updateTime:'更新时间',year:'年份',control:'管控说明',population:'人口',countyAdcode:'旗县代码',cityAdcode:'盟市代码',area_km2:'面积（平方公里）',area_mu:'面积（亩）',qualityGrade:'质量等级',grade:'等级',organicMatter:'有机质含量',ph:'pH 值',target:'治理目标',indicator:'指标',scale:'规模',reserve:'储量',rightType:'权利类型',validUntil:'有效期至',restoreType:'修复类型',protectLevel:'保护等级',canopy:'郁闭度',vegCover:'植被覆盖率',areaPct:'面积占比',level:'级别',note:'备注',threat:'威胁对象',monitor:'监测方式',riskLevel:'风险等级',depth:'深度',waterLevel:'水位',quality:'质量',heavyMetal:'重金属指标',demo:'演示数据',length:'长度',status:'状态',luClass:'土地利用类型',change:'变更情况',elevation:'高程',lane:'车道数',reclaimPotential:'复垦潜力',slope:'坡度',supplyMode:'供地方式',surveyType:'调查类型'};
const excluded=new Set(['geometry','coordinates','geom','c','layer','layerId','layerName','properties','resourceId','area','unit','aiQueryId']);
export function featurePropertyRows(feature){
  const fields={...Object.fromEntries(Object.entries(feature).filter(([key])=>!excluded.has(key))),...feature.properties};
  return Object.entries(fields).filter(([key])=>!excluded.has(key)).map(([key,value])=>({key,label:labels[key]||key,value:value===null||value===undefined||value===''?'未登记':typeof value==='boolean'?(value?'是':'否'):typeof value==='object'?JSON.stringify(value):String(value)}));
}
